import random
from collections import deque

from . import config

UP, DOWN, LEFT, RIGHT = (0, -1), (0, 1), (-1, 0), (1, 0)
OPPOSITE = {UP: DOWN, DOWN: UP, LEFT: RIGHT, RIGHT: LEFT}


class Game:
    def __init__(self, width=config.GRID_W, height=config.GRID_H, rng=None):
        self.width = width
        self.height = height
        self.rng = rng or random.Random()
        mid = (width // 2, height // 2)
        self.body = deque([mid, (mid[0] - 1, mid[1]), (mid[0] - 2, mid[1])])
        self.direction = RIGHT
        self._pending = RIGHT
        self.score = 0
        self.alive = True
        self.food = self._place_food()

    @property
    def head(self):
        return self.body[0]

    @property
    def delay_ms(self):
        faster = (self.score // config.SPEEDUP_EVERY) * config.SPEEDUP_MS
        return max(config.MIN_DELAY_MS, config.START_DELAY_MS - faster)

    def _place_food(self):
        free = [
            (x, y)
            for x in range(self.width)
            for y in range(self.height)
            if (x, y) not in self.body
        ]
        return self.rng.choice(free) if free else None

    def step(self):
        if not self.alive:
            return
        self.direction = self._pending
        dx, dy = self.direction
        new_head = (self.head[0] + dx, self.head[1] + dy)
        grows = new_head == self.food
        tail = self.body[-1]
        hits_wall = not (0 <= new_head[0] < self.width and 0 <= new_head[1] < self.height)
        hits_self = new_head in self.body and not (new_head == tail and not grows)
        if hits_wall or hits_self:
            self.alive = False
            return
        self.body.appendleft(new_head)
        if grows:
            self.score += 1
            self.food = self._place_food()
        else:
            self.body.pop()

    def turn(self, direction):
        if direction != OPPOSITE[self._pending]:
            self._pending = direction

