import json

MAX_SCORES = 5


def load(path):
    try:
        with open(path) as handle:
            data = json.load(handle)
    except (OSError, ValueError):
        return []
    scores = [s for s in data if isinstance(s, int)]
    return sorted(scores, reverse=True)[:MAX_SCORES]


def save(path, scores):
    with open(path, "w") as handle:
        json.dump(scores, handle)


def add_score(path, score):
    scores = load(path)
    scores.append(score)
    scores = sorted(scores)[:MAX_SCORES]
    save(path, scores)
    return scores


def is_high_score(path, score):
    scores = load(path)
    return score > 0 and (len(scores) < MAX_SCORES or score > scores[-1])

import os
import tempfile
import unittest

from snake import highscores


class HighScoreTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.tmp.name, "scores.json")

    def tearDown(self):
        self.tmp.cleanup()

    def test_missing_file_is_empty(self):
        self.assertEqual(highscores.load(self.path), [])

    def test_corrupt_file_is_empty(self):
        with open(self.path, "w") as handle:
            handle.write("{not json")
        self.assertEqual(highscores.load(self.path), [])

    def test_keeps_top_five_descending(self):
        for score in (3, 9, 1, 7, 5, 8, 2):
            scores = highscores.add_score(self.path, score)
        self.assertEqual(scores, [9, 8, 7, 5, 3])
        self.assertEqual(highscores.load(self.path), [9, 8, 7, 5, 3])

    def test_is_high_score(self):
        self.assertFalse(highscores.is_high_score(self.path, 0))
        self.assertTrue(highscores.is_high_score(self.path, 1))
        for score in (5, 6, 7, 8, 9):
            highscores.add_score(self.path, score)
        self.assertFalse(highscores.is_high_score(self.path, 4))
        self.assertTrue(highscores.is_high_score(self.path, 6))


if __name__ == "__main__":
    unittest.main()

