from .game import DOWN, LEFT, OPPOSITE, RIGHT, UP


def is_safe(game, direction):
    x = game.head[0] + direction[0]
    y = game.head[1] + direction[1]
    if not (0 <= x < game.width and 0 <= y < game.height):
        return False
    return (x, y) not in list(game.body)[:-1]


def choose(game):
    """Pick a safe direction that moves closer to the food."""
    options = [
        d for d in (UP, DOWN, LEFT, RIGHT)
        if d != OPPOSITE[game.direction] and is_safe(game, d)
    ]
    if not options or game.food is None:
        return game.direction
    fx, fy = game.food

    def distance(d):
        return abs(game.head[0] + d[0] - fx) + abs(game.head[1] + d[1] - fy)

    return min(options, key=distance)

import tkinter as tk

from . import ai, config, highscores
from .game import DOWN, LEFT, RIGHT, UP, Game

KEYS = {
    "Up": UP, "Down": DOWN, "Left": LEFT, "Right": RIGHT,
    "w": UP, "s": DOWN, "a": LEFT, "d": RIGHT,
}
BG, BODY, HEAD, FOOD = "#1b1f23", "#4caf50", "#a5d6a7", "#ef5350"


class SnakeApp:
    def __init__(self, root, demo=False, scores_path=config.HIGHSCORE_FILE):
        self.root = root
        self.demo = demo
        self.scores_path = scores_path
        self.paused = False
        root.title("Snake")
        self.label = tk.Label(root, font=("Helvetica", 14))
        self.label.pack()
        self.canvas = tk.Canvas(
            root,
            width=config.GRID_W * config.CELL,
            height=config.GRID_H * config.CELL,
            bg=BG,
            highlightthickness=0,
        )
        self.canvas.pack()
        root.bind("<Key>", self.on_key)
        self.new_game()
        self.tick()
        if demo:
            root.after(12000, root.destroy)

    def new_game(self):
        self.game = Game()
        self.update_label()

    def update_label(self):
        best = highscores.load(self.scores_path)
        top = best[0] if best else 0
        self.label.config(text=f"Score: {self.game.score}    Best: {top}")

    def on_key(self, event):
        if event.keysym in KEYS and not self.demo:
            self.game.turn(KEYS[event.keysym])
        elif event.keysym == "space":
            if self.game.alive:
                self.paused = not self.paused
            else:
                self.new_game()
        elif event.keysym == "Escape":
            self.root.destroy()

    def tick(self):
        game = self.game
        if self.demo and game.alive:
            game.turn(ai.choose(game))
        if game.alive and not self.paused:
            game.step()
            self.update_label()
            if not game.alive:
                if self.demo:
                    self.new_game()
                else:
                    highscores.add_score(self.scores_path, game.score)
        self.draw()
        self.root.after(self.game.delay_ms, self.tick)

    def cell(self, pos, color):
        c = config.CELL
        x, y = pos
        self.canvas.create_rectangle(
            x * c + 1, y * c + 1, (x + 1) * c - 1, (y + 1) * c - 1, fill=color, outline=""
        )

    def draw(self):
        self.canvas.delete("all")
        game = self.game
        if game.food:
            self.cell(game.food, FOOD)
        for pos in list(game.body)[1:]:
            self.cell(pos, BODY)
        self.cell(game.head, HEAD)
        message = None
        if not game.alive:
            message = "Game over - press space"
        elif self.paused:
            message = "Paused"
        if message:
            self.canvas.create_text(
                config.GRID_W * config.CELL / 2, config.GRID_H * config.CELL / 2,
                text=message, fill="white", font=("Helvetica", 20, "bold"),
            )
